const z = require("zod");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
if (typeof z.fromJSONSchema !== "function") broken("z.fromJSONSchema is not a function");
let schema;
try {
  schema = z.fromJSONSchema({ enum: ["red", "green", "blue"], description: "A color value", default: "red" });
} catch (e) { broken("fromJSONSchema threw: " + e.message); }
const ok = schema.safeParse("green");
if (!ok.success || ok.data !== "green") broken("enum schema did not accept green");
if (schema.safeParse("purple").success) broken("enum schema accepted purple");
const u = schema.safeParse(undefined);
const desc = schema.description;
if (!u.success && desc === undefined) symptom("fromJSONSchema ignores description and default on an enum schema");
if (!u.success || u.data !== "red") broken("parse(undefined) gave " + JSON.stringify(u));
if (desc !== "A color value") broken("description is " + desc);
console.log("OK: fromJSONSchema applies description and default on an enum schema");

